import json,pathlib,html
P=pathlib.Path('dist'); C=json.load(open('content/characters.json'));G=json.load(open('content/guides.json')); esc=html.escape

def shell(title,body,active='Home',description='Explore Stella Sora with character profiles, beginner guides, and a personal tier list.'):
 nav=''.join(f'<a href="{url}" class="{"active" if label==active else ""}" {"aria-current=page" if label==active else ""}>{label}</a>' for label,url in [('Home','/'),('Guides','/guides/'),('Characters','/characters/'),('Tier List','/tier-list/')])
 sidebar=f'''<aside class="wiki-sidebar"><div class="game-mark"><span class="game-monogram">S</span><div>STELLA SORA<small>GUIDE DATABASE</small></div></div><small class="nav-label">EXPLORE NOVA</small><nav aria-label="Wiki navigation">{nav}</nav><small class="nav-label">GETTING STARTED</small><a href="/guides/beginners-guide/">Beginner's guide</a><a href="/guides/team-building/">Team building</a><a href="/guides/resource-planning/">Resource planning</a><div class="sidebar-bottom"><span class="status-dot"></span> COMMUNITY FIELD GUIDE<a href="/about/">Sources & editorial notes ↗</a></div></aside>'''
 return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#4b5082"><meta name="description" content="{esc(description)}"><title>{esc(title)} · Stella Atlas</title><link rel="preload" href="/assets/fonts/Oswald-Bold.ttf" as="font" type="font/ttf" crossorigin><link rel="preload" href="/assets/fonts/Poppins-Regular.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/pages.css"><link rel="stylesheet" href="/refined.css"><link rel="stylesheet" href="/game-theme.css"></head><body><a class="skip-link" href="#main-content">Skip to content</a><header><a class="brand" href="/"><span class="brand-icon">✳</span><span>STELLA<span class="brand-light"> ATLAS</span><small>STELLA SORA • UNOFFICIAL WIKI</small></span></a><nav aria-label="Main navigation">{nav}</nav><button class="search-open" aria-label="Search">⌕ <span>Search</span><kbd>/</kbd></button></header>{sidebar}<main id="main-content">{body}</main><footer><a class="brand" href="/">✳ STELLA ATLAS</a><p>Independent fan guide. Not affiliated with Yostar.<br>Stella Sora & artwork © Yostar. Roster checked October 23, 2026.</p><a href="/about/">Sources & editorial notes ↗</a></footer><dialog id="search-dialog"><button class="close-dialog" aria-label="Close">×</button><div class="eyebrow">SEARCH THE ARCHIVE</div><h2>Where to next?</h2><label class="search-label" for="global-search">Search characters and field notes</label><input id="global-search" placeholder="Characters, guides, elements…" aria-label="Search the archive"><div id="search-results"></div></dialog><div id="toast" role="status"></div><script src="/data.js"></script><script src="/app.js"></script></body></html>'''
def write(route,title,body,active='Home',desc=None):
 d=P/route;d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(shell(title,body,active,desc or 'Explore Stella Sora with character profiles, practical guides, and your personal tier list.'))
def breadcrumb(label,parent=None):return f'<div class="breadcrumb"><a href="/">Home</a><span>/</span>{f"<a href=/{parent.lower()}/>{parent}</a><span>/</span>" if parent else ""}{esc(label)}</div>'
def head(kicker,title,sub):return f'<div class="page-heading"><div class="eyebrow">{kicker}</div><h1>{title}</h1><p>{sub}</p></div>'
def card(c):return f'''<article class="character-card" data-name="{c['name'].lower()}" data-element="{c['element']}" data-rarity="{c['rarity']}"><button class="save" data-save="{c['name']}" aria-label="Save {c['name']}" aria-pressed="false">♡</button><a class="character-open" href="/characters/{c['slug']}/"><span class="element-badge {c['element'].lower()}">{c['element']}</span><img src="{c['portrait']}" alt="{c['name']}" loading="lazy" width="400" height="500"><div class="char-info"><small>{'★'*c['rarity']}</small><h3>{c['name']} <span>↗</span></h3></div></a></article>'''
def guidecard(g,i):
 art=['firstlight-noya','chitose','shia','fuyuka','eleanor','allie','suntide-willow','firefly'][i%8]
 return f'''<a class="guide-tile" href="/guides/{g['slug']}/" data-category="{g['category']}"><div class="guide-visual v{i%4}"><span>0{i+1}</span><img src="/assets/{art}.webp" alt="" loading="lazy"><small>STELLA SORA / GUIDE</small></div><div class="guide-text"><small>{g['category'].upper()} · {g['minutes']} MIN READ</small><h3>{g['title']}</h3><p>{g['description']}</p><span class="text-link">Read the guide ↗</span></div></a>'''

hero='''<section class="hero"><div class="hero-grid"></div><div class="orbit"></div><div class="hero-copy"><div class="eyebrow"><span class="status-dot"></span> YOUR NEXT ADVENTURE STARTS HERE</div><h1>STELLA SORA<span>GUIDES & DATABASE</span></h1><p>Character profiles, practical guides, and your personal tier board. Everything in one place for your journey through Nova.</p><div class="hero-actions"><a class="button primary" href="/guides/beginners-guide/">Beginner’s guide <b>↗</b></a><a class="text-link" href="/characters/">Browse the roster →</a></div><button class="hero-search" data-open-search><span>⌕</span><span>Find a character or guide</span><kbd>/</kbd></button><div class="hero-bottom"><span>41 TREKKERS</span><i></i><span>8 GUIDES</span><i></i><span>FAN-MADE ARCHIVE</span></div></div><div class="hero-art"><div class="giant-star">✦</div><span class="hero-caption">NOVA / THE TREKKER ARCHIVE</span><img src="/assets/chitose.webp" alt="Chitose official character artwork" fetchpriority="high"><a href="/characters/chitose/" class="hero-character"><span><small>TREKKER SPOTLIGHT</small><strong>Chitose</strong><span>Aqua · 5-star Trekker</span></span><b>↗</b></a><span class="art-number">STELLA ATLAS / TREKKER ARCHIVE</span></div></section>'''
quick='<div class="quick-links" id="explore">'+''.join(f'<a href="{u}"><span class="quick-icon">{icon}</span><div><small>{k}</small><b>{t}</b><span>{sub}</span></div><i>→</i></a>' for u,icon,k,t,sub in [('/guides/','↗','01 / FIELD NOTES','Game guides','Eight paths to a better journey'),('/characters/','✧','02 / TREKKER ARCHIVE','Character database','Explore all 41 roster entries'),('/tier-list/','▥','03 / PERSONAL PLANNING','Personal tier list','Your priorities, your next adventure')])+'</div>'
home=hero+quick+'<section class="section"><div class="section-heading"><div><div class="eyebrow">LEARN THE GAME</div><h2>ESSENTIAL GUIDES</h2></div><a class="text-link" href="/guides/">All guides ↗</a></div><div class="home-guide-grid">'+''.join(guidecard(g,i) for i,g in enumerate(G[:3]))+'</div></section><section class="section characters-section"><div class="section-heading"><div><div class="eyebrow">CHARACTER DATABASE</div><h2>FEATURED TREKKERS</h2></div><a class="text-link" href="/characters/">All 41 characters ↗</a></div><div class="character-grid">'+''.join(card(next(c for c in C if c['name']==n)) for n in ['Firstlight Noya','Chitose','Allie','Fuyuka','Shia','Eleanor'])+'</div></section><section class="closing"><span>✳</span><div><small>THE JOURNEY CONTINUES</small><h2>See you in Nova.</h2><p>Stay curious. Find your next adventure.</p></div><a class="button" href="https://stellasora.global/" target="_blank" rel="noopener">Official Stella Sora ↗</a></section>'
write('','Your field guide to Nova',home)
filters='<div class="directory-tools"><label class="character-search"><span class="sr-only">Character name</span>⌕ <input id="character-search" placeholder="Search all 41 characters…" aria-label="Search characters"></label><select id="rarity-filter" aria-label="Filter by rarity"><option value="all">All rarities</option><option value="5">5 stars</option><option value="4">4 stars</option></select><button class="button saved-filter" aria-pressed="false">♡ Saved only</button></div><div class="element-filters">'+''.join(f'<button data-element-filter="{e}" class="{"selected" if e=="all" else ""}">{"All elements" if e=="all" else e}</button>' for e in ['all','Ignis','Aqua','Ventus','Terra','Lux','Umbra'])+'</div>'
write('characters','Character directory','<div class="page-wrap">'+breadcrumb('Characters')+head('THE TREKKER ARCHIVE / 41 ENTRIES','CHARACTER DATABASE','Browse the roster, compare elements, and make room for a new favorite.')+filters+'<div class="results-bar"><span id="result-count" role="status" aria-live="polite">41 characters</span><button id="clear-filters">Reset filters ↺</button></div><div class="character-grid directory-grid" id="character-grid">'+''.join(map(card,C))+'</div><p id="empty-state" hidden>No characters match these filters. Try another name or reset your filters.</p><p class="source-note">Roster and attributes cross-checked against <a href="https://www.kaiden.gg/stella-sora/characters/" target="_blank" rel="noopener">Kaiden’s character directory</a>. Official artwork is used where available. See individual pages for sources.</p></div>','Characters')
write('guides','Guides','<div class="page-wrap">'+breadcrumb('Guides')+head('LEARN THE GAME / 08 GUIDES','A clearer path <em>through Nova.</em>','From your first team to your next investment. Practical guides you can read at your own pace.')+'<div class="element-filters">'+''.join(f'<button data-guide-filter="{k}" class="{"selected" if k=="All" else ""}">{k}</button>' for k in ['All','Getting started','Team building','Exploration','Progression','Planning'])+'</div><div class="guide-directory">'+''.join(guidecard(g,i) for i,g in enumerate(G))+'</div></div>','Guides')
for i,g in enumerate(G):
 toc=''.join(f'<a href="#section-{j}"><span>0{j+1}</span>{esc(t)}</a>' for j,(t,p) in enumerate(g['sections']))
 article=''.join(f'<section id="section-{j}"><div class="eyebrow">STEP 0{j+1}</div><h2>{esc(t)}</h2><p>{esc(p)}</p></section>' for j,(t,p) in enumerate(g['sections']))
 body='<div class="page-wrap article-wrap">'+breadcrumb(g['title'],'Guides')+head(g['category'].upper()+' / FIELD NOTES',g['title'],g['description'])+f'<div class="article-meta">STELLA ATLAS EDITORIAL <span>·</span> {g["minutes"]} MIN READ <span>·</span> OCT 23, 2026</div><div class="article-layout"><aside class="toc"><small>ON THIS PAGE</small>{toc}<a href="/guides/">← All guides</a></aside><article class="reading-content">{article}<div class="editorial-note"><b>About this guide</b><p>Original beginner-oriented advice, not a version-specific build or an official Yostar recommendation. Check exact skill text, costs, and unlock conditions in your current game client. <a href="https://stellasora.global/" target="_blank" rel="noopener">Official game reference ↗</a></p></div><div class="next-read"><small>KEEP EXPLORING</small><a href="/guides/{G[(i+1)%len(G)]["slug"]}/">{G[(i+1)%len(G)]["title"]} →</a></div></article></div></div>'
 write('guides/'+g['slug'],g['title'],body,'Guides',g['description'])
variants={'Noya':'Firstlight Noya','Firstlight Noya':'Noya','Laru':'Snowish Laru','Snowish Laru':'Laru','Coronis':'Springseek Coronis','Springseek Coronis':'Coronis'}
for i,c in enumerate(C):
 peers=[x for x in C if x['element']==c['element'] and x!=c][:4]; variant=variants.get(c['name']);v=next((x for x in C if x['name']==variant),None)
 voice=f'<div><dt>Japanese voice</dt><dd>{esc(c["voice"])}</dd></div>' if c['voice'] else ''
 body='<div class="page-wrap">'+breadcrumb(c['name'],'Characters')+f'''<section class="profile-hero"><div class="profile-art" style="--accent:var(--{c['element'].lower()})"><span class="profile-watermark">{c['element'].upper()}</span><img src="{c['image']}" alt="{c['name']} artwork" fetchpriority="high"></div><div class="profile-copy"><div class="eyebrow">TREKKER ARCHIVE / {c['element'].upper()}</div><h1>{c['name']}</h1><span class="stars">{'★'*c['rarity']}</span><p>{c['name']} is a {c['rarity']}-star {c['element']} Trekker in Stella Sora. Explore this roster entry, shortlist companions, and plan your next step in Nova.</p><dl class="profile-stats"><div><dt>Element</dt><dd>{c['element']}</dd></div><div><dt>Rarity</dt><dd>{c['rarity']} stars</dd></div>{voice}</dl><button class="button primary" data-save="{c['name']}" aria-pressed="false">♡ Save character</button><a class="button" href="/tier-list/?character={c['slug']}">Set personal rank ↗</a></div></section><div class="profile-details"><article><div class="eyebrow">FIELD NOTES</div><h2>Getting to know {c['name']}</h2><p>Use {c['name']}'s {c['element']} element as a starting point for finding teammates. Then check each candidate’s current skill descriptions: who benefits, what activates the effect, and whether it supports the way you want to play.</p><p>Rarity alone does not determine the best choice for your account. Before investing, compare the resources needed with the specific problem you are trying to solve. Try a consistent encounter and change one part of your setup at a time.</p>{f'<div class="editorial-note"><b>Looking for {variant}?</b><p>This is a separate form with its own roster entry. <a href="/characters/{v["slug"]}/">Open {variant} →</a></p></div>' if v else ''}<h3>Before investing</h3><ul class="checklist"><li>Read the current skills and their activation conditions.</li><li>Identify the team slot and purpose you want to fill.</li><li>Test the interaction before committing limited materials.</li><li>Compare with alternatives you already own.</li></ul><div class="editorial-note"><b>Profile scope</b><p>Element, rarity, and artwork are sourced. The notes above are general planning advice, not a tested character build. Version-specific skill multipliers, equipment recommendations, and combat rankings are not included.</p></div></article><aside class="profile-sidebar"><small>RECOMMENDED READING</small><a href="/guides/team-building/">Build your first team ↗</a><a href="/guides/character-investment/">Choose your next investment ↗</a><a href="/guides/elements-and-roster/">Navigate the six elements ↗</a><small>PROFILE SOURCES</small><a href="{c['source']}" target="_blank" rel="noopener">Character data · Kaiden ↗</a>{'<a href="https://stellasora.global/" target="_blank" rel="noopener">Artwork & voice · Official site ↗</a>' if c['official'] else '<p>Game artwork sourced via Kaiden. © Yostar.</p>'}<p>Checked October 23, 2026</p></aside></div><section class="related-section"><div class="section-heading"><div><div class="eyebrow">EXPLORE THE ROSTER</div><h2>More {c['element']} Trekkers</h2></div><a href="/characters/?element={c['element']}" class="text-link">Browse {c['element']} ↗</a></div><div class="character-grid related-grid">{''.join(map(card,peers))}</div></section></div>'''
 write('characters/'+c['slug'],c['name']+' character profile',body,'Characters',f"Explore {c['name']}, a {c['rarity']}-star {c['element']} Trekker in Stella Sora. Profile, related characters, and planning guides.")
tier='<div class="page-wrap">'+breadcrumb('Tier List')+head('PERSONAL PLANNING / YOUR PRIORITIES','PERSONAL TIER LIST','Build a personal shortlist of all 41 Trekkers. Select a rank beside a character to move them into your board.')+'<div class="editorial-note"><b>Your personal board, not a meta ranking.</b> Use S, A, and B for your own priorities. Rankings are stored in this browser. <a href="/guides/reading-tier-lists/">How to read a tier list ↗</a></div><div class="tier-page-layout"><div><div id="tier-board" class="tier-board"></div><button id="reset-tier" class="button reset">Reset all ranks ↺</button></div><aside class="rank-picker"><label for="rank-search">Find a Trekker</label><input id="rank-search" placeholder="Search characters…"><div id="rank-list"></div></aside></div></div>'
write('tier-list','Personal tier list',tier,'Tier List')
write('about','Sources and editorial notes','<div class="page-wrap article-wrap">'+breadcrumb('Sources')+head('ABOUT THE ATLAS','A field guide, <em>made by fans.</em>','Where our information comes from, and what each page covers.')+'<article class="reading-content"><h2>Roster coverage</h2><p>The directory includes the 41 character entries listed in <a href="https://www.kaiden.gg/stella-sora/characters/">Kaiden’s Stella Sora character directory</a> when checked on October 23, 2026. Named variants are separate entries. This is a dated snapshot, not a live connection to the game.</p><h2>Artwork and attributes</h2><p>Names, elements, and rarity labels are cross-checked with the character directory. Full character artwork and Japanese voice credits are taken from the <a href="https://stellasora.global/">official Stella Sora website</a> where available. Additional character portraits are game artwork sourced through Kaiden. Stella Sora and its artwork belong to Yostar.</p><h2>Guides and character notes</h2><p>The eight guides are original introductory advice. Character pages include sourced profile attributes and general planning notes. These notes are not tested individual builds. We do not invent missing skill values, equipment recommendations, or combat results.</p><h2>Visual identity</h2><p>Typography uses Poppins and Oswald, both declared by the official Stella Sora website. The cyan, indigo, pale blue and yellow palette is adapted from its web styles. This identifies the official website fonts, not verified in-client font usage. The wiki navigation takes inspiration from Prydwen and Kaiden. Font licenses are included with the site assets.</p><h2>Your tier list and saved characters</h2><p>The tier list is a personal board. It is not an authoritative meta ranking. Saved characters and ranks stay in local browser storage; they are not automatically synced between devices. No account is required for these features.</p></article></div>')
(P/'data.js').write_text('window.ATLAS='+json.dumps({'characters':C,'guides':[{k:g[k] for k in ['slug','title','category','description']} for g in G]},ensure_ascii=False)+';')
print('Generated',len(list(P.rglob('index.html'))),'pages')
